import {depth,ensureExchange,reserved,placeOrder,cancelOrder} from './exchange.js';
const fmt=n=>Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}),quote=p=>fmt(p/100),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createExchangeUI({state,goods,modal,save,toast}){let good='maize',side='buy',type='limit',draftPrice='',draftQty='10';
 function render(selected){if(selected&&goods[selected]){good=selected;draftPrice='';}const e=ensureExchange(state),book=depth(state,good),locked=reserved(state),bestAsk=book.asks[0]?.price,bestBid=book.bids[0]?.price;const price=draftPrice||String(((side==='buy'?bestAsk:bestBid)||bestAsk||bestBid||100)/100),orders=e.orders.filter(o=>o.owner==='player'&&o.remaining&&o.status==='open');
 const rows=(items,kind)=>items.slice(0,10).map(o=>`<button class="book-row ${kind}" data-book-price="${o.price/100}"><span>${quote(o.price)}</span><span>${o.remaining}</span><span>${quote(o.price*o.remaining)}</span><i style="width:${Math.min(100,o.remaining/Math.max(...items.map(x=>x.remaining))*100)}%"></i></button>`).join('')||'<p class="book-empty">No '+(kind==='ask'?'asks':'bids')+'</p>';
 modal(`<div class="exchange"><div class="exchange-heading"><div><small>MEADOW EXCHANGE</small><h2>${esc(goods[good])} <span>/ COIN</span></h2></div><select id="ex-good" aria-label="Market">${state.offers.map(o=>`<option value="${o.good}" ${o.good===good?'selected':''}>${esc(goods[o.good])} / COIN</option>`).join('')}</select></div><p class="exchange-note">Local practice order book · finite simulated counterparties · farm coins only</p><div class="exchange-balances"><span>Available <b>${fmt(state.coins)} ◉</b></span><span>Reserved <b>${fmt(locked.coins)} ◉</b></span><span>${esc(goods[good])} <b>${state.inventory[good]||0}</b></span></div><div class="exchange-grid"><section class="order-book"><h3>Order book <small>Price · Amount · Total</small></h3><div class="book-head"><span>Price ◉</span><span>Amount</span><span>Total ◉</span></div><div class="asks">${rows(book.asks.slice(0,10).reverse(),'ask')}</div><div class="spread">${bestAsk?quote(bestAsk):'—'} <small>Spread ${bestAsk&&bestBid?quote(bestAsk-bestBid):'—'} ◉</small></div><div class="bids">${rows(book.bids,'bid')}</div></section><section class="order-ticket"><div class="ticket-sides"><button id="ex-buy" class="${side==='buy'?'active buy':''}">Buy</button><button id="ex-sell" class="${side==='sell'?'active sell':''}">Sell</button></div><label>Order type<select id="ex-type"><option value="limit" ${type==='limit'?'selected':''}>Limit</option><option value="market" ${type==='market'?'selected':''}>Market · available liquidity</option></select></label><label>Limit price · COIN<input id="ex-price" type="number" min="0.01" step="0.01" value="${esc(price)}" ${type==='market'?'disabled':''}></label><label>Amount<input id="ex-qty" type="number" min="1" max="1000" step="1" value="${esc(draftQty)}"></label><p id="ex-estimate">${type==='limit'?'Maximum order value':'Indicative value'} <b>${fmt(Number(price)*Number(draftQty))} ◉</b></p><button id="ex-submit" class="submit-${side}">${side==='buy'?'Buy':'Sell'} ${esc(goods[good])}</button><p>Limit orders reserve coins or goods. Market orders fill available quantity and cancel the remainder. Sales have a 5% fee. No fills occur without a matching order.</p></section></div><section class="my-orders"><h3>Your open orders <small>${orders.length}</small></h3>${orders.length?orders.map(o=>`<div><b class="${o.side}">${o.side.toUpperCase()}</b><span>${esc(goods[o.good])}</span><span>${quote(o.price)} ◉</span><span>${o.remaining} / ${o.quantity}</span><button data-cancel-order="${o.id}">Cancel</button></div>`).join(''):'<p>No open orders.</p>'}</section><details><summary>Recent fills · this local market</summary>${e.trades.filter(t=>t.good===good).slice(0,12).map(t=>`<div class="fill-row"><b class="${t.side}">${t.side.toUpperCase()}</b><span>${t.quantity} @ ${quote(t.price)} ◉</span><small>Farm day ${t.day}</small></div>`).join('')||'<p>No trades yet.</p>'}</details></div>`);
 const $=s=>document.querySelector(s);const retain=()=>{draftQty=$('#ex-qty').value;draftPrice=$('#ex-price').value;};$('#ex-good').onchange=()=>{retain();render($('#ex-good').value);};$('#ex-type').onchange=()=>{retain();type=$('#ex-type').value;render();};$('#ex-buy').onclick=()=>{retain();side='buy';draftPrice='';render();};$('#ex-sell').onclick=()=>{retain();side='sell';draftPrice='';render();};$('#ex-qty').oninput=$('#ex-price').oninput=()=>{retain();$('#ex-estimate').textContent='Order value '+fmt(Number(draftPrice)*Number(draftQty))+' ◉';};$('#ex-submit').onclick=()=>{retain();try{const r=placeOrder(state,{good,side,type,price:Number(draftPrice),quantity:Number(draftQty)});save();toast(r.filled+' filled'+(r.status==='open'?' · '+r.remaining+' resting':r.remaining?' · unfilled amount cancelled':''));render();}catch(e){toast(e.message);}};for(const b of document.querySelectorAll('[data-book-price]'))b.onclick=()=>{retain();draftPrice=b.dataset.bookPrice;type='limit';render();};for(const b of document.querySelectorAll('[data-cancel-order]'))b.onclick=()=>{try{cancelOrder(state,b.dataset.cancelOrder);save();render();toast('Order cancelled; reserved balance released.');}catch(e){toast(e.message);}};
 }return {open:render};
}
